ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = * (char **)data;
    ext3_fsblk_t block = 1;

    if (strncmp(options, "sb=", 3) == 0) {
        char *endptr;
        block = simple_strtoul(options + 3, &endptr, 0);
        if (endptr == options + 3) {
            return 1; // Invalid number
        }

        // Check for invalid characters after the block number
        while (*endptr && isspace(*endptr)) {
            endptr++;
        }

        if (*endptr != '\0') {
            printk(KERN_ERR "Invalid characters after superblock block number\n");
            return 1;
        }

        // Update the data pointer to remaining options
        *data = endptr;
    }

    return block;
}

ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = (char *)*data;
    ext3_fsblk_t block = 1;

    if (!options || memcmp(options, "sb=", 3) != 0) {
        return 1;
    }

    options += 3; // Skip "sb="
    char *endptr;
    block = (ext3_fsblk_t)simple_strtoul(options, &endptr, 0);

    if (endptr == options) {
        // No digits found
        return 1;
    }

    if (*endptr != '\0' && *endptr != ',' && *endptr != ' ') {
        // Invalid characters after the block number
        printk(KERN_ERR "Invalid characters after superblock block number.\n");
        return 1;
    }

    *data = (void *)endptr;
    return block;
}

ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = *data;
