}

ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = (char *)*data;
    unsigned long block;
    char *endptr;

    if (!options || strncmp(options, "sb=", 3) != 0)
        return 1;

    block = simple_strtoul(options + 3, &endptr, 0);
    if (endptr == options + 3 || (*endptr != '\0' && *endptr != ',' && *endptr != ':')) {
        printk(KERN_ERR "Invalid superblock block number in options\n");
        return 1;
    }

    *data = (void *)endptr;
    return block;
}

ext3_fsblk_t get_superblock_block(void **data, struct super_block *sb) {
    char *options = (char *)*data;
    ext3_fsblk_t block = 1;

    if (strncmp(options, "sb=", 3) == 0) {
        char *endptr;
        block = simple_strtoul(options + 3, &endptr, 0);
        if (endptr == options + 3 || *endptr != '\0') {
            printk(KERN_ERR "Invalid block number in superblock option\n");
            block = 1;
        } else {
            *data = (void *)endptr;
        }
    }

    return block;
}
